  p_platform text,
  p_token_hash text,
  p_token_last_four text default null
)
returns void
language sql
security definer
set search_path = public
as $$
  insert into notification_device_tokens (
    user_id,
    platform,
    token_hash,
    token_last_four,
    enabled,
    last_seen_at,
    updated_at
  )
  values (
    auth.uid(),
    p_platform,
    p_token_hash,
    p_token_last_four,
    true,
    now(),
    now()
  )
  on conflict (user_id, token_hash)
  do update set
    platform = excluded.platform,
    token_last_four = excluded.token_last_four,
    enabled = true,
    last_seen_at = now(),
    updated_at = now();
$$;

