  where collection_id = any(seed_collection_ids)
     or payment_id in (
       select id from public.payments
       where collection_id = any(seed_collection_ids)
     );

  delete from public.payments
  where collection_id = any(seed_collection_ids);

  delete from public.collections
  where id = any(seed_collection_ids);
end;
$$;

