    raw_body,
    body_hash,
    client_envelope_id,
    receiver_momo_number_hash,
    received_at_device,
    parse_status
  ) values (
    p_collection_id,
    p_receiver_user_id,
    trim(p_raw_sender),
    trim(p_raw_body),
    clean_body_hash,
    p_client_envelope_id,
    clean_receiver_hash,
    p_received_at_device,
    'pending'
  )
  returning * into inserted_row;

  return jsonb_build_object(
    'id', inserted_row.id,
    'parse_status', inserted_row.parse_status,
    'replay', false
  );
end;
$$;

