          ''phone_masked'', public.mask_phone(ordered.whatsapp_phone),
          ''admin_access'', ordered.admin_active
        )
      ) order by ordered.admin_rank
    ), ''[]''::jsonb),
    ''total'', (select count(*) from filtered)
  ) into v_result
  from ordered;

  return coalesce(
    v_result,
    jsonb_build_object(''rows'', ''[]''::jsonb, ''total'', 0)
  );
end;
